<?php

declare(strict_types=1);

namespace Architex\Platform\Fees;

use Architex\Platform\Audit\AuditService;
use Architex\Platform\Identity\Identifier;
use DateTimeImmutable;
use PDO;

final readonly class FeeCalculatorService
{
    private const PROFESSIONS=['architect','engineer','civil_engineer','structural_engineer','electrical_engineer','mechanical_engineer','fire_engineer','quantity_surveyor','town_planner','land_surveyor','landscape_architect','interior_designer','construction_project_manager'];
    private const FORMULAS=['sliding_scale','percentage_of_cost','stage_apportioned','time_based','area_unit','hybrid'];
    public function __construct(private PDO $pdo){}

    /** @param array<string,mixed> $input @return array<string,mixed> */
    public function createSource(string $organisationId,string $userId,string $role,array $input):array
    {
        $this->assertAdmin($organisationId,$userId,$role);$profession=$this->profession($input['profession']??null);$body=$this->text($input['body']??null,120,'invalid_fee_source');$title=$this->text($input['title']??null,255,'invalid_fee_source');$date=$this->date($input['effectiveDate']??null);$url=$input['sourceUrl']??null;if($url!==null&&($this->text($url,1000,'invalid_fee_source')!==$url||filter_var($url,FILTER_VALIDATE_URL)===false||parse_url($url,PHP_URL_SCHEME)!=='https'))throw new FeeException('invalid_fee_source');$metadata=$input['metadata']??null;if(!is_array($metadata)||($metadata!==[]&&array_is_list($metadata)))throw new FeeException('invalid_fee_source');
        $id=Identifier::generate();$source=['profession'=>$profession,'body'=>$body,'title'=>$title,'sourceUrl'=>$url,'effectiveDate'=>$date,'metadata'=>$metadata];$this->pdo->prepare("INSERT INTO fee_source_versions(id,organisation_id,profession,body,title,source_url,effective_date,source_sha256,source_metadata,created_by) VALUES(UNHEX(:id),UNHEX(:organisation_id),:profession,:body,:title,:url,:effective_date,:sha256,:metadata,UNHEX(:user_id))")->execute(['id'=>$id,'organisation_id'=>$organisationId,'profession'=>$profession,'body'=>$body,'title'=>$title,'url'=>$url,'effective_date'=>$date,'sha256'=>hash('sha256',$this->json($source)),'metadata'=>$this->json($metadata),'user_id'=>$userId]);(new AuditService($this->pdo))->append($organisationId,$userId,'fee_source.created','fee_source_version',$id,['profession'=>$profession,'title'=>$title,'effectiveDate'=>$date]);return['id'=>$id,'status'=>'draft']+$source;
    }

    public function verifySource(string $organisationId,string $userId,string $role,string $sourceId):void
    {
        $this->assertAdmin($organisationId,$userId,$role);$statement=$this->pdo->prepare("UPDATE fee_source_versions SET status='verified',reviewed_by=UNHEX(:user_id),reviewed_at=UTC_TIMESTAMP(6) WHERE id=UNHEX(:id) AND organisation_id=UNHEX(:organisation_id) AND status='draft'");$statement->execute(['user_id'=>$userId,'id'=>$sourceId,'organisation_id'=>$organisationId]);if($statement->rowCount()!==1)throw new FeeException('fee_source_not_reviewable');(new AuditService($this->pdo))->append($organisationId,$userId,'fee_source.verified','fee_source_version',$sourceId,[]);
    }

    /** @param array<string,mixed> $input @return array<string,mixed> */
    public function createDefinition(string $organisationId,string $userId,string $role,array $input):array
    {
        $this->assertAdmin($organisationId,$userId,$role);$profession=$this->profession($input['profession']??null);$name=$this->text($input['name']??null,180,'invalid_fee_definition');$version=$input['version']??null;if(!is_string($version)||preg_match('/\A\d+\.\d+\.\d+\z/',$version)!==1)throw new FeeException('invalid_fee_definition');$formula=$input['formulaType']??null;if(!is_string($formula)||!in_array($formula,self::FORMULAS,true))throw new FeeException('invalid_fee_definition');$sourceId=$input['sourceVersionId']??null;if(!is_string($sourceId))throw new FeeException('invalid_fee_definition');$source=$this->pdo->prepare('SELECT profession FROM fee_source_versions WHERE id=UNHEX(:id) AND organisation_id=UNHEX(:organisation_id)');$source->execute(['id'=>$sourceId,'organisation_id'=>$organisationId]);if($source->fetchColumn()!==$profession)throw new FeeException('fee_source_not_found');$configuration=$input['configuration']??null;if(!is_array($configuration)||array_is_list($configuration))throw new FeeException('invalid_fee_definition');$this->validateConfiguration($formula,$configuration);
        $id=Identifier::generate();try{$this->pdo->prepare('INSERT INTO fee_calculator_definitions(id,organisation_id,profession,name,version,formula_type,source_version_id,configuration,created_by) VALUES(UNHEX(:id),UNHEX(:organisation_id),:profession,:name,:version,:formula,UNHEX(:source_id),:configuration,UNHEX(:user_id))')->execute(['id'=>$id,'organisation_id'=>$organisationId,'profession'=>$profession,'name'=>$name,'version'=>$version,'formula'=>$formula,'source_id'=>$sourceId,'configuration'=>$this->json($configuration),'user_id'=>$userId]);}catch(\PDOException){throw new FeeException('fee_definition_version_exists');}(new AuditService($this->pdo))->append($organisationId,$userId,'fee_definition.created','fee_calculator_definition',$id,['profession'=>$profession,'version'=>$version,'formulaType'=>$formula]);return['id'=>$id,'profession'=>$profession,'name'=>$name,'version'=>$version,'formulaType'=>$formula,'sourceVersionId'=>$sourceId,'configuration'=>$configuration,'status'=>'draft'];
    }

    public function verifyDefinition(string $organisationId,string $userId,string $role,string $definitionId):void
    {
        $this->assertAdmin($organisationId,$userId,$role);$statement=$this->pdo->prepare("UPDATE fee_calculator_definitions d JOIN fee_source_versions s ON s.id=d.source_version_id AND s.organisation_id=d.organisation_id AND s.status='verified' SET d.status='verified',d.reviewed_by=UNHEX(:user_id),d.reviewed_at=UTC_TIMESTAMP(6) WHERE d.id=UNHEX(:id) AND d.organisation_id=UNHEX(:organisation_id) AND d.status='draft'");$statement->execute(['user_id'=>$userId,'id'=>$definitionId,'organisation_id'=>$organisationId]);if($statement->rowCount()!==1)throw new FeeException('fee_definition_not_reviewable');(new AuditService($this->pdo))->append($organisationId,$userId,'fee_definition.verified','fee_calculator_definition',$definitionId,[]);
    }

    /** @param array<string,mixed> $input @return array<string,mixed> */
    public function calculate(string $organisationId,string $userId,string $definitionId,array $input):array
    {
        $this->assertMember($organisationId,$userId);$statement=$this->pdo->prepare("SELECT d.profession,d.name,d.version,d.formula_type,d.configuration,LOWER(HEX(s.id)) source_id,s.body,s.title,s.source_url,s.effective_date,s.source_sha256,s.status source_status,d.status definition_status FROM fee_calculator_definitions d JOIN fee_source_versions s ON s.id=d.source_version_id AND s.organisation_id=d.organisation_id WHERE d.id=UNHEX(:id) AND d.organisation_id=UNHEX(:organisation_id)");$statement->execute(['id'=>$definitionId,'organisation_id'=>$organisationId]);$row=$statement->fetch();if(!is_array($row))throw new FeeException('fee_definition_not_found');if($row['definition_status']!=='verified'||$row['source_status']!=='verified')throw new FeeException('fee_definition_not_verified');$config=json_decode($row['configuration'],true,32,JSON_THROW_ON_ERROR);if(!is_array($config))throw new FeeException('invalid_fee_definition');
        $projectValue=$this->number($input['projectValue']??null,0);$complexityId=$input['complexityId']??null;$complexities=$config['complexities'];if(!is_string($complexityId)||!isset($complexities[$complexityId])||!is_numeric($complexities[$complexityId]))throw new FeeException('invalid_fee_complexity');$complexity=(float)$complexities[$complexityId];
        $splits=$input['categorySplits']??null;if(!is_array($splits)||$splits===[]||abs(array_sum(array_map('floatval',$splits))-1)>.001)throw new FeeException('invalid_fee_category_splits');$categoryFactor=0.0;foreach($splits as$id=>$split){if(!is_string($id)||!is_numeric($split)||!isset($config['categories'][$id])||(float)$split<0)throw new FeeException('invalid_fee_category_splits');$categoryFactor+=(float)$split*(float)$config['categories'][$id];}
        $hourly=$this->lineTotal($input['hourlyLines']??[],'hours','rate');$units=$this->unitTotal($input['unitLines']??[]);$base=$this->base((string)$row['formula_type'],$projectValue,$hourly,$units,$config);$guideline=$this->money($base*$complexity*$categoryFactor);
        $selected=$input['selectedStages']??null;if(!is_array($selected))throw new FeeException('invalid_fee_stages');$stageFactor=0.0;foreach($config['stages'] as$stage){$choice=$selected[$stage['id']]??['applicable'=>true,'reduction'=>0];if(!is_array($choice)||!is_bool($choice['applicable']??null)||!is_numeric($choice['reduction']??null)||(float)$choice['reduction']<0||(float)$choice['reduction']>1)throw new FeeException('invalid_fee_stages');if($choice['applicable'])$stageFactor+=(float)$stage['weight']*(1-(float)$choice['reduction']);}$stageAdjusted=$this->money($guideline*$stageFactor);$before=$stageAdjusted;$warnings=[];
        if(isset($input['professionalOverride'])){$override=$input['professionalOverride'];if(!is_array($override)||!is_numeric($override['amount']??null)||(float)$override['amount']<0||trim((string)($override['reason']??''))==='')throw new FeeException('invalid_fee_override');$before=$this->money((float)$override['amount']);$warnings[]='Professional override applied; the original calculated fee remains in this snapshot.';}
        $disbursements=$this->amountLines($input['disbursements']??[]);$statutory=$this->amountLines($input['statutoryFees']??[]);$discount=$input['discount']??['percentage'=>0,'reason'=>''];if(!is_array($discount)||!is_numeric($discount['percentage']??null)||(float)$discount['percentage']<0||(float)$discount['percentage']>1||((float)$discount['percentage']>0&&trim((string)($discount['reason']??''))===''))throw new FeeException('invalid_fee_discount');$percentage=(float)$discount['percentage'];$professionalDiscount=$this->money($before*$percentage);$disbursementDiscount=($discount['appliesToDisbursements']??false)===true?$this->money($disbursements*$percentage):0.0;$statutoryDiscount=($discount['appliesToStatutoryFees']??false)===true?$this->money($statutory*$percentage):0.0;$discountAmount=$this->money($professionalDiscount+$disbursementDiscount+$statutoryDiscount);$professionalAfter=$this->money($before-$professionalDiscount);$disbursementsAfter=$this->money($disbursements-$disbursementDiscount);$statutoryAfter=$this->money($statutory-$statutoryDiscount);
        $vatApplicable=$input['vatApplicable']??null;if(!is_bool($vatApplicable))throw new FeeException('invalid_fee_vat');$vatRate=(float)$config['vatRate'];$vat=$vatApplicable?$this->money(($professionalAfter+$disbursementsAfter)*$vatRate):0.0;$total=$this->money($professionalAfter+$disbursementsAfter+$statutoryAfter+$vat);
        return['definition'=>['id'=>$definitionId,'profession'=>$row['profession'],'name'=>$row['name'],'version'=>$row['version'],'formulaType'=>$row['formula_type'],'configuration'=>$config],'source'=>['id'=>$row['source_id'],'body'=>$row['body'],'title'=>$row['title'],'sourceUrl'=>$row['source_url'],'effectiveDate'=>$row['effective_date'],'sha256'=>$row['source_sha256']],'guidelineProfessionalFee'=>$guideline,'stageAdjustedFee'=>$stageAdjusted,'professionalFeeBeforeDiscount'=>$before,'discountPercentage'=>$percentage,'discountAmount'=>$discountAmount,'professionalFeeAfterDiscount'=>$professionalAfter,'disbursementsTotal'=>$disbursements,'statutoryFeesTotal'=>$statutory,'vatRate'=>$vatRate,'vatAmount'=>$vat,'totalInclVat'=>$total,'warnings'=>$warnings,'classification'=>'professional_decision_support','advisoryOnly'=>true,'limitations'=>'Indicative proposal aid only; not a fixed tariff or legal opinion. The responsible professional must verify the source, scope, fees, tax and terms before issue.'];
    }

    /** @return list<array<string,mixed>> */
    public function definitions(string $organisationId,string $userId):array{$this->assertMember($organisationId,$userId);$statement=$this->pdo->prepare("SELECT LOWER(HEX(d.id)) id,d.profession,d.name,d.version,d.formula_type formulaType,d.status,d.configuration,LOWER(HEX(s.id)) sourceVersionId,s.body sourceBody,s.title sourceTitle,s.effective_date sourceEffectiveDate,s.status sourceStatus FROM fee_calculator_definitions d JOIN fee_source_versions s ON s.id=d.source_version_id AND s.organisation_id=d.organisation_id WHERE d.organisation_id=UNHEX(:organisation_id) ORDER BY d.created_at DESC,d.id");$statement->execute(['organisation_id'=>$organisationId]);$rows=[];foreach($statement as$row){$row['configuration']=json_decode($row['configuration'],true,32,JSON_THROW_ON_ERROR);$rows[]=$row;}return$rows;}

    /** @param array<string,mixed> $config */
    private function validateConfiguration(string $formula,array $config):void
    {
        if(!is_numeric($config['vatRate']??null)||(float)$config['vatRate']<0||(float)$config['vatRate']>1)throw new FeeException('invalid_fee_definition');foreach(['complexities','categories']as$key)if(!is_array($config[$key]??null)||$config[$key]===[])throw new FeeException('invalid_fee_definition');$stages=$config['stages']??null;if(!is_array($stages)||$stages===[])throw new FeeException('invalid_fee_definition');$weight=0.0;foreach($stages as$stage){if(!is_array($stage)||!is_string($stage['id']??null)||!is_string($stage['name']??null)||!is_numeric($stage['weight']??null)||(float)$stage['weight']<0)throw new FeeException('invalid_fee_definition');$weight+=(float)$stage['weight'];}if(abs($weight-1)>.001)throw new FeeException('invalid_fee_definition');if(in_array($formula,['percentage_of_cost','stage_apportioned','hybrid'],true)&&(!is_numeric($config['percentage']??null)||(float)$config['percentage']<0))throw new FeeException('invalid_fee_definition');if($formula==='sliding_scale'){if(!is_numeric($config['minimumFee']??null)||!is_array($config['brackets']??null)||$config['brackets']===[])throw new FeeException('invalid_fee_definition');foreach($config['brackets']as$bracket)if(!is_array($bracket)||!array_key_exists('upTo',$bracket)||($bracket['upTo']!==null&&!is_numeric($bracket['upTo']))||!is_numeric($bracket['rate']??null)||(float)$bracket['rate']<0)throw new FeeException('invalid_fee_definition');}}
    /** @param array<string,mixed> $config */
    private function base(string $formula,float $value,float $hourly,float $units,array $config):float{return match($formula){'sliding_scale'=>$this->sliding($value,$config),'percentage_of_cost','stage_apportioned'=>$value*(float)$config['percentage'],'time_based'=>$hourly,'area_unit'=>$units,'hybrid'=>$value*(float)$config['percentage']+$hourly+$units,default=>throw new FeeException('invalid_fee_definition')};}
    /** @param array<string,mixed> $config */
    private function sliding(float $value,array $config):float{$fee=0.0;$lower=0.0;foreach($config['brackets']as$bracket){$upper=$bracket['upTo']===null?$value:(float)$bracket['upTo'];$portion=max(0,min($value,$upper)-$lower);$fee+=$portion*(float)$bracket['rate'];$lower=$upper;if($value<=$upper)break;}return max((float)$config['minimumFee'],$fee);}
    private function lineTotal(mixed $lines,string $quantity,string $rate):float{if(!is_array($lines))throw new FeeException('invalid_fee_lines');$total=0.0;foreach($lines as$line){if(!is_array($line)||!is_string($line['label']??null)||!is_numeric($line[$quantity]??null)||!is_numeric($line[$rate]??null)||(float)$line[$quantity]<0||(float)$line[$rate]<0)throw new FeeException('invalid_fee_lines');$total+=(float)$line[$quantity]*(float)$line[$rate];}return$total;}
    private function unitTotal(mixed $lines):float{if(!is_array($lines))throw new FeeException('invalid_fee_lines');$total=0.0;foreach($lines as$line){if(!is_array($line)||!is_string($line['label']??null)||!is_numeric($line['quantity']??null)||!is_numeric($line['unitRate']??null)||!is_numeric($line['factor']??1)||(float)$line['quantity']<0||(float)$line['unitRate']<0||(float)($line['factor']??1)<0)throw new FeeException('invalid_fee_lines');$total+=(float)$line['quantity']*(float)$line['unitRate']*(float)($line['factor']??1);}return$total;}
    private function amountLines(mixed $lines):float{if(!is_array($lines))throw new FeeException('invalid_fee_lines');$total=0.0;foreach($lines as$line){if(!is_array($line)||!is_string($line['label']??null)||!is_numeric($line['amount']??null)||(float)$line['amount']<0)throw new FeeException('invalid_fee_lines');$total+=(float)$line['amount'];}return$this->money($total);}
    private function assertAdmin(string $organisationId,string $userId,string $role):void{$this->assertMember($organisationId,$userId);if(!in_array($role,['owner','admin'],true))throw new FeeException('fee_admin_required');}
    private function assertMember(string $organisationId,string $userId):void{$statement=$this->pdo->prepare("SELECT COUNT(*) FROM organisation_memberships WHERE organisation_id=UNHEX(:organisation_id) AND user_id=UNHEX(:user_id) AND status='active'");$statement->execute(['organisation_id'=>$organisationId,'user_id'=>$userId]);if((int)$statement->fetchColumn()!==1)throw new FeeException('membership_not_found');}
    private function profession(mixed $value):string{if(!is_string($value)||!in_array($value,self::PROFESSIONS,true))throw new FeeException('invalid_fee_profession');return$value;}
    private function date(mixed $value):string{if(!is_string($value)||preg_match('/\A\d{4}-\d{2}-\d{2}\z/',$value)!==1||!($date=DateTimeImmutable::createFromFormat('!Y-m-d',$value))||$date->format('Y-m-d')!==$value)throw new FeeException('invalid_fee_source');return$value;}
    private function text(mixed $value,int $max,string $reason):string{if(!is_string($value)||($value=trim($value))===''||mb_strlen($value)>$max)throw new FeeException($reason);return$value;}
    private function number(mixed $value,float $min):float{if(!is_numeric($value)||(float)$value<$min)throw new FeeException('invalid_fee_value');return(float)$value;}
    /** @param array<string,mixed> $value */
    private function json(array $value):string{return json_encode($value,JSON_THROW_ON_ERROR|JSON_UNESCAPED_SLASHES|JSON_PRESERVE_ZERO_FRACTION);}
    private function money(float $value):float{return round($value,2,PHP_ROUND_HALF_UP);}
}
